-- What the hub decides a project move by, out of its state (`moves.state`,
-- JSON), is columns of its row: the session it starts
-- (`target_instance_id`: its row is held from the move's start, moves.ts
-- `holds`), the ask parked for the person's "Move it" (`ask_id`: an answer
-- finds its move by it, moves.ts `answer`) and whether they said it
-- (`approved`). The rest of the state stays JSON, in `learned`: what the
-- machines answered (the snapshot, the large files, the progress), the
-- steps and the paths.
--
-- `state` was NOT NULL: every move has one. A state that reads whole (every
-- part of its shape: db/move-states-unread.ts `STATE`) is placed as it is:
-- its session's id, its ask's id (null when none was parked), `approved`
-- true where it said so and false where it said nothing, and the rest in
-- `learned`. Nothing is recomputed.
--
-- A state that is there and does not read whole (not JSON, not an object,
-- or a part of another kind) is kept as stored in `state_unread`,
-- `learned` null, `approved` false: it is no move the hub runs, shows,
-- answers or cancels, so it cancels or removes nothing it cannot name. Its
-- session's id and its ask's id are placed where they are text: the
-- session row it names stays held (never woken by a send; the person may
-- remove it) and is marked failed as the hub starts (moves.ts `resume`),
-- and its parked ask, which nothing can carry out, is settled then as any
-- such ask is. Today's reader threw on it. The step before this migration
-- (db/migrate.ts `moves-unread`) logs each by its id and why.
--
-- Every JSON function sits inside a CASE that proved `state` JSON (and an
-- object, where it reads a key): SQLite may run either side of an AND
-- first.
ALTER TABLE `moves` ADD `learned` text;--> statement-breakpoint
ALTER TABLE `moves` ADD `target_instance_id` text;--> statement-breakpoint
ALTER TABLE `moves` ADD `ask_id` text;--> statement-breakpoint
ALTER TABLE `moves` ADD `approved` integer DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE `moves` ADD `state_unread` text;--> statement-breakpoint
UPDATE `moves` SET `state_unread` = CASE WHEN CASE WHEN json_valid(state) THEN coalesce((json_type(state, '$') IN ('object') AND (json_type(state, '$.bigFiles') IN ('array') AND CASE WHEN json_type(state, '$.bigFiles') = 'array' THEN NOT EXISTS (SELECT 1 FROM json_each(state, '$.bigFiles') e0 WHERE NOT coalesce((json_type(state, e0.fullkey) IN ('object') AND (json_type(state, e0.fullkey || '.bytes') IN ('integer', 'real')) AND (json_type(state, e0.fullkey || '.path') IN ('text'))), 0)) ELSE 0 END) AND (json_type(state, '$.bytes') IN ('integer', 'real')) AND ((json_type(state, '$.from') IN ('object') AND (json_type(state, '$.from.kind') IN ('text') AND (json_type(state, '$.from.kind') = 'text' AND json_extract(state, '$.from.kind') = 'hub'))) OR (json_type(state, '$.from') IN ('object') AND (json_type(state, '$.from.kind') IN ('text') AND (json_type(state, '$.from.kind') = 'text' AND json_extract(state, '$.from.kind') = 'outside')) AND (json_type(state, '$.from.host') IN ('text')))) AND (json_type(state, '$.ignoredSecrets') IN ('array') AND CASE WHEN json_type(state, '$.ignoredSecrets') = 'array' THEN NOT EXISTS (SELECT 1 FROM json_each(state, '$.ignoredSecrets') e0 WHERE NOT coalesce((json_type(state, e0.fullkey) IN ('text')), 0)) ELSE 0 END) AND (json_type(state, '$.ignores') IN ('true', 'false')) AND (json_type(state, '$.promptUuid') IN ('text')) AND (json_type(state, '$.snapshotBranch') IN ('text')) AND (json_type(state, '$.sourceHome') IN ('text')) AND (json_type(state, '$.sourcePath') IN ('text')) AND (json_type(state, '$.steps') IN ('array') AND CASE WHEN json_type(state, '$.steps') = 'array' THEN NOT EXISTS (SELECT 1 FROM json_each(state, '$.steps') e0 WHERE NOT coalesce((json_type(state, e0.fullkey) IN ('text') AND (json_type(state, e0.fullkey) = 'text' AND json_extract(state, e0.fullkey) IN ('approval', 'snapshot', 'clone', 'lfs', 'start'))), 0)) ELSE 0 END) AND (json_type(state, '$.targetHome') IN ('text')) AND (json_type(state, '$.targetInstanceId') IN ('text')) AND (json_type(state, '$.targetPath') = 'text' AND substr(json_extract(state, '$.targetPath'), 1, 1) = '/' AND json_extract(state, '$.targetPath') = trim(json_extract(state, '$.targetPath'), ' ' || char(9, 10, 11, 12, 13)) AND instr(json_extract(state, '$.targetPath'), '//') = 0 AND instr(json_extract(state, '$.targetPath') || '/', '/./') = 0 AND instr(json_extract(state, '$.targetPath') || '/', '/../') = 0 AND (json_extract(state, '$.targetPath') = '/' OR substr(json_extract(state, '$.targetPath'), -1, 1) <> '/')) AND (json_type(state, '$.approved') IS NULL OR (json_type(state, '$.approved') IN ('true', 'false'))) AND (json_type(state, '$.ask') IS NULL OR (json_type(state, '$.ask') IN ('object') AND (json_type(state, '$.ask.bigFiles') IN ('array') AND CASE WHEN json_type(state, '$.ask.bigFiles') = 'array' THEN NOT EXISTS (SELECT 1 FROM json_each(state, '$.ask.bigFiles') e0 WHERE NOT coalesce((json_type(state, e0.fullkey) IN ('object') AND (json_type(state, e0.fullkey || '.bytes') IN ('integer', 'real')) AND (json_type(state, e0.fullkey || '.path') IN ('text'))), 0)) ELSE 0 END) AND (json_type(state, '$.ask.details') IN ('array') AND CASE WHEN json_type(state, '$.ask.details') = 'array' THEN NOT EXISTS (SELECT 1 FROM json_each(state, '$.ask.details') e0 WHERE NOT coalesce((json_type(state, e0.fullkey) IN ('text')), 0)) ELSE 0 END) AND (json_type(state, '$.ask.gitInit') IN ('true', 'false')) AND (json_type(state, '$.ask.lines') IN ('array') AND CASE WHEN json_type(state, '$.ask.lines') = 'array' THEN NOT EXISTS (SELECT 1 FROM json_each(state, '$.ask.lines') e0 WHERE NOT coalesce((json_type(state, e0.fullkey) IN ('text')), 0)) ELSE 0 END) AND (json_type(state, '$.ask.title') IN ('text')) AND (json_type(state, '$.ask.key') IS NULL OR (json_type(state, '$.ask.key') IN ('text'))))) AND (json_type(state, '$.askId') IS NULL OR (json_type(state, '$.askId') IN ('text'))) AND (json_type(state, '$.cloneCredential') IS NULL OR (json_type(state, '$.cloneCredential') IN ('true', 'false') AND json_type(state, '$.cloneCredential') = 'true')) AND (json_type(state, '$.cloneUrl') IS NULL OR (json_type(state, '$.cloneUrl') IN ('text'))) AND (json_type(state, '$.error') IS NULL OR (json_type(state, '$.error') IN ('object') AND (json_type(state, '$.error.message') IN ('text')) AND (json_type(state, '$.error.stage') IN ('text') AND (json_type(state, '$.error.stage') = 'text' AND json_extract(state, '$.error.stage') IN ('approval', 'snapshot', 'clone', 'lfs', 'start'))) AND (json_type(state, '$.error.detail') IS NULL OR (json_type(state, '$.error.detail') IN ('text'))))) AND (json_type(state, '$.kept') IS NULL OR (json_type(state, '$.kept') IN ('text'))) AND (json_type(state, '$.lfs') IS NULL OR (json_type(state, '$.lfs') IN ('object') AND (json_type(state, '$.lfs.bytes') IN ('integer', 'real')) AND (json_type(state, '$.lfs.files') IN ('integer', 'real')))) AND (json_type(state, '$.lfsFile') IS NULL OR (json_type(state, '$.lfsFile') IN ('object') AND (json_type(state, '$.lfsFile.bytes') IN ('integer', 'real')) AND (json_type(state, '$.lfsFile.file') IN ('text')) AND (json_type(state, '$.lfsFile.total') IN ('integer', 'real')))) AND (json_type(state, '$.moved') IS NULL OR (json_type(state, '$.moved') IN ('text'))) AND (json_type(state, '$.progress') IS NULL OR (json_type(state, '$.progress') IN ('object') AND (json_type(state, '$.progress.bytes') IN ('integer', 'real')) AND (json_type(state, '$.progress.total') IN ('integer', 'real')))) AND (json_type(state, '$.root') IS NULL OR (json_type(state, '$.root') IN ('text'))) AND (json_type(state, '$.snapshot') IS NULL OR (json_type(state, '$.snapshot') IN ('object') AND (json_type(state, '$.snapshot.base') IN ('text', 'null')) AND (json_type(state, '$.snapshot.branch') IN ('text')) AND (json_type(state, '$.snapshot.commit') IN ('text')) AND (json_type(state, '$.snapshot.files') IN ('integer', 'real')) AND (json_type(state, '$.snapshot.sourceBranch') IN ('text', 'null')) AND (json_type(state, '$.snapshot.hub') IS NULL OR (json_type(state, '$.snapshot.hub') IN ('object') AND (json_type(state, '$.snapshot.hub.projectId') IN ('text')) AND (json_type(state, '$.snapshot.hub.root') IS NULL OR (json_type(state, '$.snapshot.hub.root') IN ('text'))))) AND (json_type(state, '$.snapshot.hubLfs') IS NULL OR (json_type(state, '$.snapshot.hubLfs') IN ('array') AND CASE WHEN json_type(state, '$.snapshot.hubLfs') = 'array' THEN NOT EXISTS (SELECT 1 FROM json_each(state, '$.snapshot.hubLfs') e0 WHERE NOT coalesce((json_type(state, e0.fullkey) IN ('object') AND (json_type(state, e0.fullkey || '.oid') IN ('text')) AND (json_type(state, e0.fullkey || '.path') IN ('text')) AND (json_type(state, e0.fullkey || '.size') IN ('integer', 'real'))), 0)) ELSE 0 END)))) AND (json_type(state, '$.stayed') IS NULL OR (json_type(state, '$.stayed') IN ('text'))) AND (json_type(state, '$.stoppedAt') IS NULL OR (json_type(state, '$.stoppedAt') IN ('text') AND (json_type(state, '$.stoppedAt') = 'text' AND json_extract(state, '$.stoppedAt') IN ('approval', 'snapshot', 'clone', 'lfs', 'start'))))), 0) ELSE 0 END THEN NULL ELSE CAST(`state` AS TEXT) END;--> statement-breakpoint
UPDATE `moves` SET `target_instance_id` = CASE WHEN json_valid(state) THEN CASE WHEN json_type(state) = 'object' THEN CASE WHEN json_type(state, '$.targetInstanceId') = 'text' THEN json_extract(state, '$.targetInstanceId') END END END, `ask_id` = CASE WHEN json_valid(state) THEN CASE WHEN json_type(state) = 'object' THEN CASE WHEN json_type(state, '$.askId') = 'text' THEN json_extract(state, '$.askId') END END END, `approved` = coalesce(CASE WHEN json_valid(state) THEN CASE WHEN json_type(state) = 'object' THEN CASE WHEN state_unread IS NULL THEN json_type(state, '$.approved') = 'true' END END END, 0), `learned` = CASE WHEN json_valid(state) THEN CASE WHEN json_type(state) = 'object' THEN CASE WHEN state_unread IS NULL THEN json_remove(state, '$.targetInstanceId', '$.askId', '$.approved') END END END;--> statement-breakpoint
CREATE INDEX `moves_target_instance` ON `moves` (`target_instance_id`);--> statement-breakpoint
CREATE INDEX `moves_ask` ON `moves` (`ask_id`);--> statement-breakpoint
ALTER TABLE `moves` DROP COLUMN `state`;